shell_commands:
cat << 'EOF' > test-snippet.ts
    it('runs onError and afterSession when it throws', async () => {
      let caughtError: Error | undefined;
      let afterSessionCalled = false;
      const errorToThrow = new Error('boom');

      const hooks: OrchestratorHooks = {
        beforeSession: async () => {
          throw errorToThrow;
        },
        onError: async (_session, error) => {
          caughtError = error;
        },
        afterSession: async () => {
          afterSessionCalled = true;
        },
      };

      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));

      expect({outcome, caughtError, afterSessionCalled}).toEqual({
        outcome: 'boom',
        caughtError: errorToThrow,
        afterSessionCalled: true,
      });
    });
EOF
